import type { LetterField, LetterType, Profile } from '@/types';

const toneSignOffs: Record<string, string> = {
  formal: 'با تجدید احترام',
  'semi-formal': 'با تجدید احترام',
  informal: 'با سپاس',
  friendly: 'با صمیمیت',
};

const toneOpenings: Record<string, string> = {
  formal: 'با سلام و احترام،',
  'semi-formal': 'با سلام و احترام،',
  informal: 'با سلام و احترام،',
  friendly: 'با سلام و آرزوی خیر،',
};

/**
 * AI engine — conversation orchestration utilities.
 *
 * Letter type discovery and field definitions are now fully dynamic and
 * generated by the AI (deepseek.ts → aiDiscoverLetterType). This module
 * provides local helpers for question phrasing, validation, and the
 * fallback document builder.
 */

export interface ConversationState {
  step: number;
  fields: { required: LetterField[]; optional: LetterField[] };
  collectedValues: Record<string, string>;
  isComplete: boolean;
}

/** Initialize a conversation from a discovered document */
export function initConversation(
  requiredFields: LetterField[],
  optionalFields: LetterField[],
): ConversationState {
  return {
    step: 0,
    fields: { required: requiredFields, optional: optionalFields },
    collectedValues: {},
    isComplete: false,
  };
}

/**
 * Build a structured "Smart Form" message following the Kateb prompt template.
 * Categorizes fields into "essential" and "optional" sections with numbered questions.
 */
export function buildSmartFormMessage(
  docType: string,
  purpose: string,
  tone: string,
  requiredFields: LetterField[],
  optionalFields: LetterField[],
): string {
  const toneLabels: Record<string, string> = {
    formal: 'رسمی',
    'semi-formal': 'نیمه‌رسمی',
    informal: 'محترمانه',
    friendly: 'صمیمی',
  };

  let message = `نوع خروجی تشخیص‌داده‌شده:\n${docType}\n\n`;
  message += `هدف:\n${purpose}\n\n`;
  message += `لحن پیشنهادی:\n${toneLabels[tone] ?? tone}\n\n`;

  message += `لطفاً اطلاعات ضروری زیر را وارد کنید:\n\n`;
  requiredFields.forEach((field, i) => {
    message += `${i + 1}. ${field.hint ?? field.label}\n`;
  });

  if (optionalFields.length > 0) {
    message += `\nاطلاعات اختیاری برای بهتر شدن خروجی:\n\n`;
    optionalFields.forEach((field, i) => {
      message += `${requiredFields.length + i + 1}. ${field.hint ?? field.label}\n`;
    });
  }

  message += `\nپس از دریافت پاسخ‌ها، متن نهایی را برای شما آماده می‌کنم.`;

  return message;
}

/** Generate an intelligent, context-aware question for a field */
export function generateQuestion(
  field: LetterField,
  _profile: Profile | undefined,
  _letterType: LetterType,
  _collectedSoFar: Record<string, string>,
): string {
  let question = field.hint ?? field.label;

  if (field.type === 'date') {
    question = `${field.hint ?? field.label} لطفاً تاریخ را به شمسی وارد کنید (مثلاً: ۱۴۰۵/۰۵/۱۵).`;
  } else if (field.type === 'select') {
    question = `${field.hint ?? field.label} یکی از گزینه‌ها را انتخاب کنید.`;
  } else if (field.optional) {
    question = `${field.hint ?? field.label} (این بخش اختیاری است، اما در صورت تکمیل، مکتوب شما کامل‌تر خواهد بود.)`;
  }

  return question;
}

/** Validate a user's answer for a field */
export function validateAnswer(
  field: LetterField,
  answer: string,
): { valid: boolean; error?: string } {
  if (field.required && !answer.trim()) {
    return { valid: false, error: 'این فیلد اجباری است.' };
  }
  if (field.type === 'date' && answer.trim()) {
    const clean = answer.replace(/[۰-۹]/g, (d) => String('۰۱۲۳۴۵۶۷۸۹'.indexOf(d)));
    if (!/^\d{4}\/\d{1,2}\/\d{1,2}$/.test(clean.trim())) {
      return { valid: false, error: 'فرمت تاریخ صحیح نیست. مثال: ۱۴۰۵/۰۵/۱۵' };
    }
  }
  if (field.type === 'number' && answer.trim()) {
    const clean = answer.replace(/[۰-۹]/g, (d) => String('۰۱۲۳۴۵۶۷۸۹'.indexOf(d)));
    if (!/^\d+$/.test(clean.trim())) {
      return { valid: false, error: 'لطفاً فقط عدد وارد کنید.' };
    }
  }
  return { valid: true };
}

/**
 * Replace actual user data in generated letter content with {{placeholder}} tokens.
 * Used when saving a template so the preview never exposes personal info.
 */
function normalizePrivateValue(value: string): string {
  return value
    .replace(/[۰-۹]/g, (digit) => String('۰۱۲۳۴۵۶۷۸۹'.indexOf(digit)))
    .replace(/[\s\-_.()،؛:/\\]/g, '')
    .toLowerCase();
}

function profileFieldLabel(key: string): string {
  const normalizedKey = key.toLowerCase().replace(/[\s_-]/g, '');
  if (normalizedKey.includes('phone') || normalizedKey.includes('mobile') || normalizedKey.includes('tel') || normalizedKey.includes('تماس') || normalizedKey.includes('موبایل') || normalizedKey.includes('تلفن')) return 'شماره تماس';
  if (normalizedKey.includes('employee') || normalizedKey.includes('personnel') || normalizedKey.includes('پرسنلی')) return 'کد پرسنلی';
  if (normalizedKey.includes('national') || normalizedKey.includes('ملی')) return 'کد ملی';
  return key;
}

export function anonymizeContent(
  content: string,
  letterType: LetterType,
  profile: Profile | null,
  fieldValues: Record<string, string>,
): string {
  const protectedValues: { value: string; placeholder: string }[] = [];

  if (profile) {
    protectedValues.push(
      { value: profile.fullName, placeholder: '{{نام و نام خانوادگی}}' },
      { value: profile.nationalId, placeholder: '{{کد ملی}}' },
      { value: profile.employeeCode, placeholder: '{{کد پرسنلی}}' },
      { value: profile.organization, placeholder: '{{سازمان}}' },
      { value: profile.jobTitle, placeholder: '{{سمت}}' },
    );
    for (const [key, value] of Object.entries(profile.extraFields ?? {})) {
      protectedValues.push({ value, placeholder: `{{${profileFieldLabel(key)}}}` });
    }
  }

  for (const field of letterType.fields) {
    protectedValues.push({ value: fieldValues[field.id] ?? '', placeholder: `{{${field.label}}}` });
  }

  const usableValues = protectedValues
    .filter(({ value }) => value.trim().length > 1)
    .sort((a, b) => b.value.length - a.value.length);

  const anonymizedLines = content.split('\n').map((line) => {
    const normalizedLine = normalizePrivateValue(line);
    const match = usableValues.find(({ value }) => normalizedLine.includes(normalizePrivateValue(value)));
    if (match) return match.placeholder;

    const sensitivePlaceholders: string[] = [];
    if (/(شماره\s*(تماس|تلفن)|تلفن|موبایل|همراه|phone|mobile|tel)/i.test(line)) sensitivePlaceholders.push('{{شماره تماس}}');
    if (/(کد|شماره)\s*(پرسنلی|کارمندی|کارکنان)|employee|personnel/i.test(line)) sensitivePlaceholders.push('{{کد پرسنلی}}');
    if (/(کد\s*ملی|national\s*id)/i.test(line)) sensitivePlaceholders.push('{{کد ملی}}');
    if (sensitivePlaceholders.length > 0) return [...new Set(sensitivePlaceholders)].join(' ');
    return line;
  });

  let result = anonymizedLines.join('\n');
  const today = new Date().toLocaleDateString('fa-IR');
  if (today) result = result.split(today).join('{{تاریخ}}');
  return result;
}

/** Build a local fallback document (used when AI generation fails) */
export function buildLetter(
  letterType: LetterType,
  profile: Profile | null,
  fieldValues: Record<string, string>,
): string {
  const today = new Date().toLocaleDateString('fa-IR');
  const tone = letterType.tone ?? 'formal';
  const opening = toneOpenings[tone] ?? 'با سلام و احترام،';
  const signOff = toneSignOffs[tone] ?? 'با تجدید احترام';
  const isFormal = tone === 'formal';
  const isFriendly = tone === 'friendly';

  const details = letterType.fields
    .filter((field) => fieldValues[field.id]?.trim())
    .map((field) => isFormal
      ? `در خصوص ${field.label}، ${fieldValues[field.id].trim()} اعلام می‌گردد.`
      : `${field.label}: ${fieldValues[field.id].trim()}`)
    .join(' ');

  if (isFriendly && !profile) {
    return `${today}

گیرنده محترم

موضوع: ${letterType.title}

${opening}

${details || 'با توجه به موضوع مطرح‌شده، خواهشمند است درخواست حاضر بررسی و نتیجه آن اعلام شود.'}

${signOff}
اینجانب`;
  }

  if (!profile) {
    return `${isFormal ? 'بسمه تعالی\n\n' : ''}${today}

گیرنده محترم

موضوع: ${letterType.title}

${opening}

${details || 'با توجه به موضوع مطرح‌شده، خواهشمند است درخواست حاضر بررسی و نتیجه آن اعلام شود.'}

${isFormal ? 'با عنایت به مراتب فوق، خواهشمند است دستور فرمایید موضوع بررسی و اقدامات لازم انجام شود. پیشاپیش از توجه و مساعدت شما سپاسگزارم.' : ''}

${signOff}
اینجانب`;
  }

  return `${isFormal ? 'بسمه تعالی\n\n' : ''}${today}

گیرنده محترم

موضوع: ${letterType.title}

${opening}

${isFormal
  ? `این‌جانب ${profile.fullName}، دارای کد ملی ${profile.nationalId}، کد پرسنلی ${profile.employeeCode}، ${profile.jobTitle} در ${profile.organization}، به استحضار می‌رساند:`
  : `${profile.fullName}${profile.jobTitle ? `، ${profile.jobTitle}` : ''}${profile.organization ? `، ${profile.organization}` : ''}`}

${details || 'با توجه به موضوع مطرح‌شده، خواهشمند است درخواست حاضر بررسی و نتیجه آن اعلام شود.'}

${isFormal ? 'با عنایت به مراتب فوق و با توجه به ضرورت موضوع، خواهشمند است دستور فرمایید درخواست این‌جانب بررسی شده و در صورت صلاحدید، اقدامات لازم در این خصوص انجام پذیرد. پیشاپیش از توجه و مساعدت جناب‌عالی سپاسگزارم.' : ''}

${signOff}،
${profile.fullName}
${profile.jobTitle}${profile.organization ? ` - ${profile.organization}` : ''}`;
}
